import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as a,f as t}from"./app-49128265.js";const e={},p=t(`<h1 id="spring-boot-整合-redis" tabindex="-1"><a class="header-anchor" href="#spring-boot-整合-redis" aria-hidden="true">#</a> Spring Boot 整合 Redis</h1><h2 id="引入相关依赖" tabindex="-1"><a class="header-anchor" href="#引入相关依赖" aria-hidden="true">#</a> 引入相关依赖</h2><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
   <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>org.springframework.boot<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
   <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>spring-boot-starter-data-redis<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
   <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>org.apache.commons<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
   <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>commons-pool2<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="spring-boot-项目核心配置" tabindex="-1"><a class="header-anchor" href="#spring-boot-项目核心配置" aria-hidden="true">#</a> Spring Boot 项目核心配置</h2><blockquote><p>以下是采用的集群配置的方式</p></blockquote><div class="language-properties line-numbers-mode" data-ext="properties"><pre class="language-properties"><code><span class="token key attr-name">server</span><span class="token punctuation">:</span>
<span class="token key attr-name">  port</span><span class="token punctuation">:</span> <span class="token value attr-value">8080</span>

<span class="token key attr-name">spring</span><span class="token punctuation">:</span>
<span class="token key attr-name">  redis</span><span class="token punctuation">:</span>
<span class="token key attr-name">    database</span><span class="token punctuation">:</span> <span class="token value attr-value">0</span>
<span class="token key attr-name">    timeout</span><span class="token punctuation">:</span> <span class="token value attr-value">3000</span>
<span class="token key attr-name">    password</span><span class="token punctuation">:</span> <span class="token value attr-value">XXX</span>
<span class="token comment">    # 集群节点</span>
<span class="token key attr-name">    cluster</span><span class="token punctuation">:</span>
<span class="token key attr-name">      nodes</span><span class="token punctuation">:</span> <span class="token value attr-value">192.168.0.61:8001,192.168.0.62:8002,192.168.0.63:8003,192.168.0.61:8004,192.168.0.62:8005,192.168.0.63:8006</span>
<span class="token key attr-name">   lettuce</span><span class="token punctuation">:</span>
<span class="token key attr-name">      pool</span><span class="token punctuation">:</span>
<span class="token comment">      	#连接池中的最大空闲连接</span>
<span class="token key attr-name">        max-idle</span><span class="token punctuation">:</span> <span class="token value attr-value">50</span>
<span class="token key attr-name">        min-idle</span><span class="token punctuation">:</span> <span class="token value attr-value">10</span>
<span class="token comment">        #连接池最大连接数，若为负，则表示没有任何限制</span>
<span class="token key attr-name">        max-active</span><span class="token punctuation">:</span> <span class="token value attr-value">100</span>
<span class="token comment">        #连接池最大阻塞等待时间，若为负，则表示没有任何限制</span>
<span class="token key attr-name">        max-wait</span><span class="token punctuation">:</span> <span class="token value attr-value">1000</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="自动配置" tabindex="-1"><a class="header-anchor" href="#自动配置" aria-hidden="true">#</a> 自动配置</h2><p>当开发者在项目中引入了 Spring Data Redis ，并且配置了 Redis 的基本信息，此时，自动化配置就会生效。</p><p>我们从 Spring Boot 中 Redis 的自动化配置类中就可以看出端倪：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Configuration</span>
<span class="token annotation punctuation">@ConditionalOnClass</span><span class="token punctuation">(</span><span class="token class-name">RedisOperations</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@EnableConfigurationProperties</span><span class="token punctuation">(</span><span class="token class-name">RedisProperties</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@Import</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token class-name">LettuceConnectionConfiguration</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token class-name">JedisConnectionConfiguration</span><span class="token punctuation">.</span><span class="token keyword">class</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">RedisAutoConfiguration</span> <span class="token punctuation">{</span>
        <span class="token annotation punctuation">@Bean</span>
        <span class="token annotation punctuation">@ConditionalOnMissingBean</span><span class="token punctuation">(</span>name <span class="token operator">=</span> <span class="token string">&quot;redisTemplate&quot;</span><span class="token punctuation">)</span>
        <span class="token keyword">public</span> <span class="token class-name">RedisTemplate</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Object</span><span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">&gt;</span></span> <span class="token function">redisTemplate</span><span class="token punctuation">(</span>
                        <span class="token class-name">RedisConnectionFactory</span> redisConnectionFactory<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">UnknownHostException</span> <span class="token punctuation">{</span>
                <span class="token class-name">RedisTemplate</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Object</span><span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">&gt;</span></span> template <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">RedisTemplate</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                template<span class="token punctuation">.</span><span class="token function">setConnectionFactory</span><span class="token punctuation">(</span>redisConnectionFactory<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token keyword">return</span> template<span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token annotation punctuation">@Bean</span>
        <span class="token annotation punctuation">@ConditionalOnMissingBean</span>
        <span class="token keyword">public</span> <span class="token class-name">StringRedisTemplate</span> <span class="token function">stringRedisTemplate</span><span class="token punctuation">(</span>
                        <span class="token class-name">RedisConnectionFactory</span> redisConnectionFactory<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">UnknownHostException</span> <span class="token punctuation">{</span>
                <span class="token class-name">StringRedisTemplate</span> template <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">StringRedisTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                template<span class="token punctuation">.</span><span class="token function">setConnectionFactory</span><span class="token punctuation">(</span>redisConnectionFactory<span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token keyword">return</span> template<span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个自动化配置类很好理解：</p><ol><li>首先标记这个是一个配置类，同时该配置在 RedisOperations 存在的情况下才会生效(即项目中引入了 Spring Data Redis)</li><li>然后导入在 application.properties 中配置的属性</li><li>然后再导入连接池信息（如果存在的话）</li><li>最后，提供了两个 Bean ，RedisTemplate 和 StringRedisTemplate ，其中 StringRedisTemplate 是 RedisTemplate 的子类，两个的方法基本一致，不同之处主要体现在操作的数据类型不同，RedisTemplate 中的两个泛型都是 Object ，意味者存储的 key 和 value 都可以是一个对象，而 StringRedisTemplate 的 两个泛型都是 String ，意味者 StringRedisTemplate 的 key 和 value 都只能是字符串。如果开发者没有提供相关的 Bean ，这两个配置就会生效，否则不会生效。</li></ol><h2 id="访问代码" tabindex="-1"><a class="header-anchor" href="#访问代码" aria-hidden="true">#</a> 访问代码</h2><p>可以直接注入 StringRedisTemplate 或者 RedisTemplate 来使用：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@RestController</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">IndexController</span> <span class="token punctuation">{</span>

    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Logger</span> logger <span class="token operator">=</span> <span class="token class-name">LoggerFactory</span><span class="token punctuation">.</span><span class="token function">getLogger</span><span class="token punctuation">(</span><span class="token class-name">IndexController</span><span class="token punctuation">.</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token annotation punctuation">@Autowired</span>
    <span class="token keyword">private</span> <span class="token class-name">StringRedisTemplate</span> stringRedisTemplate<span class="token punctuation">;</span>

    <span class="token annotation punctuation">@RequestMapping</span><span class="token punctuation">(</span><span class="token string">&quot;/test_cluster&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testCluster</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">InterruptedException</span> <span class="token punctuation">{</span>
       stringRedisTemplate<span class="token punctuation">.</span><span class="token function">opsForValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string">&quot;qiuchi&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;666&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
       <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>stringRedisTemplate<span class="token punctuation">.</span><span class="token function">opsForValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;qiuchi&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="stringredistemplate-与-redistemplate-详解" tabindex="-1"><a class="header-anchor" href="#stringredistemplate-与-redistemplate-详解" aria-hidden="true">#</a> StringRedisTemplate 与 RedisTemplate 详解</h2><p>Spring 封装了 RedisTemplate 对象来进行对 Redis 进行各种操作，它支持所有的 Redis 原生的 API。在 RedisTemplate 中提供了几个常用的接口方法的使用，分别是:</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">private</span> <span class="token class-name">ValueOperations</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">K</span><span class="token punctuation">,</span> <span class="token class-name">V</span><span class="token punctuation">&gt;</span></span> valueOps<span class="token punctuation">;</span>
<span class="token keyword">private</span> <span class="token class-name">HashOperations</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">K</span><span class="token punctuation">,</span> <span class="token class-name">V</span><span class="token punctuation">&gt;</span></span> hashOps<span class="token punctuation">;</span>
<span class="token keyword">private</span> <span class="token class-name">ListOperations</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">K</span><span class="token punctuation">,</span> <span class="token class-name">V</span><span class="token punctuation">&gt;</span></span> listOps<span class="token punctuation">;</span>
<span class="token keyword">private</span> <span class="token class-name">SetOperations</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">K</span><span class="token punctuation">,</span> <span class="token class-name">V</span><span class="token punctuation">&gt;</span></span> setOps<span class="token punctuation">;</span>
<span class="token keyword">private</span> <span class="token class-name">ZSetOperations</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">K</span><span class="token punctuation">,</span> <span class="token class-name">V</span><span class="token punctuation">&gt;</span></span> zSetOps<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>​</p><p>RedisTemplate中定义了对5种数据结构操作</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code>redisTemplate<span class="token punctuation">.</span><span class="token function">opsForValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span><span class="token comment">//操作字符串</span>
redisTemplate<span class="token punctuation">.</span><span class="token function">opsForHash</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span><span class="token comment">//操作hash</span>
redisTemplate<span class="token punctuation">.</span><span class="token function">opsForList</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span><span class="token comment">//操作list</span>
redisTemplate<span class="token punctuation">.</span><span class="token function">opsForSet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span><span class="token comment">//操作set</span>
redisTemplate<span class="token punctuation">.</span><span class="token function">opsForZSet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span><span class="token comment">//操作有序set</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>StringRedisTemplate 继承自 RedisTemplate，也一样拥有上面这些操作。</p><p>StringRedisTemplate 默认采用的是 String 的序列化策略，保存的 key 和 value 都是采用此策略序列化保存的。</p><p>RedisTemplate 默认采用的是 JDK 的序列化策略，保存的 key 和 value 都是采用此策略序列化保存的。</p><p><strong>Redis客户端命令对应的RedisTemplate中的方法列表：</strong></p><table><thead><tr><th><strong>String类型结构</strong></th><th></th></tr></thead><tbody><tr><td>Redis</td><td>RedisTemplate rt</td></tr><tr><td>set key value</td><td>rt.opsForValue().set(&quot;key&quot;,&quot;value&quot;)</td></tr><tr><td>get key</td><td>rt.opsForValue().get(&quot;key&quot;)</td></tr><tr><td>del key</td><td>rt.delete(&quot;key&quot;)</td></tr><tr><td>strlen key</td><td>rt.opsForValue().size(&quot;key&quot;)</td></tr><tr><td>getset key value</td><td>rt.opsForValue().getAndSet(&quot;key&quot;,&quot;value&quot;)</td></tr><tr><td>getrange key start end</td><td>rt.opsForValue().get(&quot;key&quot;,start,end)</td></tr><tr><td>append key value</td><td>rt.opsForValue().append(&quot;key&quot;,&quot;value&quot;)</td></tr><tr><td></td><td></td></tr><tr><td><strong>Hash结构</strong></td><td></td></tr><tr><td>hmset key field1 value1 field2 value2...</td><td>rt.opsForHash().putAll(&quot;key&quot;,map) //map是一个集合对象</td></tr><tr><td>hset key field value</td><td>rt.opsForHash().put(&quot;key&quot;,&quot;field&quot;,&quot;value&quot;)</td></tr><tr><td>hexists key field</td><td>rt.opsForHash().hasKey(&quot;key&quot;,&quot;field&quot;)</td></tr><tr><td>hgetall key</td><td>rt.opsForHash().entries(&quot;key&quot;) //返回Map对象</td></tr><tr><td>hvals key</td><td>rt.opsForHash().values(&quot;key&quot;) //返回List对象</td></tr><tr><td>hkeys key</td><td>rt.opsForHash().keys(&quot;key&quot;) //返回List对象</td></tr><tr><td>hmget key field1 field2...</td><td>rt.opsForHash().multiGet(&quot;key&quot;,keyList)</td></tr><tr><td>hsetnx key field value</td><td>rt.opsForHash().putIfAbsent(&quot;key&quot;,&quot;field&quot;,&quot;value&quot;</td></tr><tr><td>hdel key field1 field2</td><td>rt.opsForHash().delete(&quot;key&quot;,&quot;field1&quot;,&quot;field2&quot;)</td></tr><tr><td>hget key field</td><td>rt.opsForHash().get(&quot;key&quot;,&quot;field&quot;)</td></tr><tr><td></td><td></td></tr><tr><td><strong>List结构</strong></td><td></td></tr><tr><td>lpush list node1 node2 node3...</td><td>rt.opsForList().leftPush(&quot;list&quot;,&quot;node&quot;)</td></tr><tr><td>rt.opsForList().leftPushAll(&quot;list&quot;,list) //list是集合对象</td><td></td></tr><tr><td>rpush list node1 node2 node3...</td><td>rt.opsForList().rightPush(&quot;list&quot;,&quot;node&quot;)</td></tr><tr><td>rt.opsForList().rightPushAll(&quot;list&quot;,list) //list是集合对象</td><td></td></tr><tr><td>lindex key index</td><td>rt.opsForList().index(&quot;list&quot;, index)</td></tr><tr><td>llen key</td><td>rt.opsForList().size(&quot;key&quot;)</td></tr><tr><td>lpop key</td><td>rt.opsForList().leftPop(&quot;key&quot;)</td></tr><tr><td>rpop key</td><td>rt.opsForList().rightPop(&quot;key&quot;)</td></tr><tr><td>lpushx list node</td><td>rt.opsForList().leftPushIfPresent(&quot;list&quot;,&quot;node&quot;)</td></tr><tr><td>rpushx list node</td><td>rt.opsForList().rightPushIfPresent(&quot;list&quot;,&quot;node&quot;)</td></tr><tr><td>lrange list start end</td><td>rt.opsForList().range(&quot;list&quot;,start,end)</td></tr><tr><td>lrem list count value</td><td>rt.opsForList().remove(&quot;list&quot;,count,&quot;value&quot;)</td></tr><tr><td>lset key index value</td><td>rt.opsForList().set(&quot;list&quot;,index,&quot;value&quot;)</td></tr><tr><td></td><td></td></tr><tr><td><strong>Set结构</strong></td><td></td></tr><tr><td>sadd key member1 member2...</td><td>rt.boundSetOps(&quot;key&quot;).add(&quot;member1&quot;,&quot;member2&quot;,...)</td></tr><tr><td>rt.opsForSet().add(&quot;key&quot;, set) //set是一个集合对象</td><td></td></tr><tr><td>scard key</td><td>rt.opsForSet().size(&quot;key&quot;)</td></tr><tr><td>sidff key1 key2</td><td>rt.opsForSet().difference(&quot;key1&quot;,&quot;key2&quot;) //返回一个集合对象</td></tr><tr><td>sinter key1 key2</td><td>rt.opsForSet().intersect(&quot;key1&quot;,&quot;key2&quot;)//同上</td></tr><tr><td>sunion key1 key2</td><td>rt.opsForSet().union(&quot;key1&quot;,&quot;key2&quot;)//同上</td></tr><tr><td>sdiffstore des key1 key2</td><td>rt.opsForSet().differenceAndStore(&quot;key1&quot;,&quot;key2&quot;,&quot;des&quot;)</td></tr><tr><td>sinter des key1 key2</td><td>rt.opsForSet().intersectAndStore(&quot;key1&quot;,&quot;key2&quot;,&quot;des&quot;)</td></tr><tr><td>sunionstore des key1 key2</td><td>rt.opsForSet().unionAndStore(&quot;key1&quot;,&quot;key2&quot;,&quot;des&quot;)</td></tr><tr><td>sismember key member</td><td>rt.opsForSet().isMember(&quot;key&quot;,&quot;member&quot;)</td></tr><tr><td>smembers key</td><td>rt.opsForSet().members(&quot;key&quot;)</td></tr><tr><td>spop key</td><td>rt.opsForSet().pop(&quot;key&quot;)</td></tr><tr><td>srandmember key count</td><td>rt.opsForSet().randomMember(&quot;key&quot;,count)</td></tr><tr><td>srem key member1 member2...</td><td>rt.opsForSet().remove(&quot;key&quot;,&quot;member1&quot;,&quot;member2&quot;,...)</td></tr></tbody></table>`,26),o=[p];function l(i,c){return s(),a("div",null,o)}const r=n(e,[["render",l],["__file","12redis_spring.html.vue"]]);export{r as default};
